   RenderSettings.ambientSkyColor=theme==2?new Color(.17f,.22f,.4f):new Color(.32f,.4f,.5f);RenderSettings.ambientEquatorColor=theme==2?new Color(.12f,.18f,.27f):new Color(.4f,.28f,.23f);
   RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=theme==2?.00065f:.0004f;RenderSettings.fogColor=theme==2?new Color(.13f,.18f,.3f):new Color(.68f,.4f,.28f);
   var sky=new Material(Shader.Find("Aether/RushSky"));sky.SetColor("_Top",theme==2?new Color(.018f,.035f,.12f):new Color(.14f,.22f,.38f));sky.SetColor("_Horizon",theme==2?new Color(.21f,.2f,.4f):new Color(1,.49f,.22f));sky.SetFloat("_Storm",theme==2?1:0);RenderSettings.skybox=sky;DynamicGI.UpdateEnvironment();Presentation.Probe(transform,new Vector3(0,10,60));
