  void CombineRushSector(Transform root){var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){var r=mf.GetComponent<MeshRenderer>();if(!r)continue;var m=r.sharedMaterial;if(!groups.ContainsKey(m))groups[m]=new List<CombineInstance>();groups[m].Add(new CombineInstance{mesh=mf.sharedMesh,transform=root.worldToLocalMatrix*mf.transform.localToWorldMatrix});r.enabled=false;}foreach(var group in groups){var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(group.Value.ToArray());var o=new GameObject("Sector mesh");o.transform.SetParent(root,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;o.AddComponent<MeshRenderer>().sharedMaterial=group.Key;o.AddComponent<OwnedMesh>();}}
  void RushGate(float z,string label,Material light){var root=new GameObject(label+" gate").transform;root.SetParent(transform);root.position=new Vector3(0,5,z);var dark=ModelLibrary.Material("Rush gate",new Color(.05f,.075f,.095f));for(int s=-1;s<=1;s+=2){CarParts.Part(root,"Gate column",PrimitiveType.Cube,new Vector3(s*11,4,0),new Vector3(1.2f,8,1.2f),dark);CarParts.Part(root,"Gate strip",PrimitiveType.Cube,new Vector3(s*11,4,-.65f),new Vector3(.3f,7,.08f),light);}CarParts.Part(root,"Gate crossbar",PrimitiveType.Cube,new Vector3(0,8,0),new Vector3(23,1.6f,1.3f),dark);var t=new GameObject("Gate label").AddComponent<TextMesh>();t.transform.SetParent(root,false);t.transform.localPosition=new Vector3(0,8,-.7f);t.text=label;t.fontSize=72;t.characterSize=.35f;t.anchor=TextAnchor.MiddleCenter;t.color=Color.white;for(int x=0;x<12;x++)for(int row=0;row<2;row++)CarParts.Part(root,"Finish checker",PrimitiveType.Cube,new Vector3(x*2-11,.03f,row*2),new Vector3(2,.035f,2),ModelLibrary.Material("Rush grid "+(x+row)%2,(x+row)%2==0?Color.white:Color.black));}
