 public class RushHazard:MonoBehaviour {
  public TrackWorld track;public int kind;public float phase;public bool active;Renderer warning;Game game;float rockTimer;readonly Dictionary<Vehicle,float> cooldown=new Dictionary<Vehicle,float>();
  public void Build(){var m=new Material(Shader.Find("Aether/Toon"));m.color=kind==0?new Color(.11f,.13f,.19f):new Color(1,.44f,.12f);var bed=TrackWorld.Cube("Warning lane",transform.position+Vector3.up*.035f,new Vector3(5.5f,.04f,15),m,false);bed.transform.SetParent(transform);warning=bed.GetComponent<Renderer>();for(int s=-1;s<=1;s+=2)CarParts.Part(transform,"Hazard lane edge",PrimitiveType.Cube,new Vector3(s*2.8f,.08f,0),new Vector3(.12f,.07f,15),ModelLibrary.Material("Hazard glow "+kind,kind==2?new Color(.3f,.6f,1):new Color(1,.4f,.1f),.7f));}
  void Update(){if(!game)game=FindAnyObjectByType<Game>();if(!game||!game.RaceSimulationActive)return;float cycle=Mathf.Repeat(game.raceTime+phase,6);active=kind==0||cycle>3;warning.material.color=active?(kind==2?new Color(.1f,.55f,1):kind==1?new Color(1,.28f,.07f):new Color(.065f,.075f,.1f)):new Color(.45f,.28f,.08f)*( .7f+.3f*Mathf.Sin(cycle*9));if(kind==1&&active&&Time.time>rockTimer&&game.player&&Mathf.Abs(game.player.transform.position.z-transform.position.z)<170){rockTimer=Time.time+3;var rock=GameObject.CreatePrimitive(PrimitiveType.Sphere);rock.name="Falling canyon boulder";rock.transform.SetParent(track.transform);rock.transform.position=transform.position+Vector3.up*22;rock.transform.localScale=Vector3.one*2.6f;rock.GetComponent<Renderer>().sharedMaterial=ModelLibrary.Material("Falling stone",new Color(.4f,.21f,.12f));var body=rock.AddComponent<Rigidbody>();body.mass=900;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;Destroy(rock,6);}
   if(!active)return;foreach(var v in game.racers){var p=transform.InverseTransformPoint(v.transform.position);if(v.finished||Mathf.Abs(p.x)>2.8f||Mathf.Abs(p.z)>7.5f||p.y>3||p.y< -1)continue;if(cooldown.TryGetValue(v,out float next)&&Time.time<next)continue;cooldown[v]=Time.time+3;if(kind==0){if(v.shield>0)v.shield=0;else v.oilFor=2.5f;}else if(kind==2){if(v.shield>0)v.shield=0;else{v.empFor=2;v.Hit(Vector3.up*3);}}if(v.player)game.Toast(kind==0?"Oil trap · grip reduced":kind==2?"Electric lane · boost interrupted":"Falling rocks · change lanes");}
  }
  void OnDestroy(){if(warning)Destroy(warning.sharedMaterial);}
 }
 public class RushTrafficSystem:MonoBehaviour {
  public TrackWorld track;Game game;readonly List<Rigidbody> cars=new List<Rigidbody>();readonly List<float> lanes=new List<float>(),speeds=new List<float>();
  void Start(){game=FindAnyObjectByType<Game>();for(int i=0;i<18;i++){var root=new GameObject("Rush traffic "+i);root.transform.SetParent(transform);root.layer=10;var model=ModelLibrary.Create(CarSpec.All[(i+2)%10].name,root.transform);float lane=new[]{-9f,-3f,3f,9f}[i%4];float speed=i%3==0?19:-15-i%5;root.transform.SetPositionAndRotation(new Vector3(lane,5.12f,170+i*92),Quaternion.Euler(0,speed<0?180:0,0));var col=root.AddComponent<BoxCollider>();col.center=new Vector3(0,.65f,0);col.size=new Vector3(1.9f,1,4.3f);var body=root.AddComponent<Rigidbody>();body.mass=240;body.angularDamping=.5f;body.maxAngularVelocity=18;root.AddComponent<RushTrafficBody>();body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;cars.Add(body);lanes.Add(lane);speeds.Add(speed);CarParts.Apply(model,new SavedCar{body=(i+2)%10,paint=i*3%32});}}
  void FixedUpdate(){if(!game||!game.player)return;for(int i=0;i<cars.Count;i++){var body=cars[i];if(!game.RaceSimulationActive){body.linearVelocity=Vector3.zero;continue;}var damage=body.GetComponent<RushTrafficBody>();if(damage.disabled)continue;var p=body.position;float z=game.player.transform.position.z;bool outOfRange=p.z<z-150||p.z>z+1800||p.y<2||Mathf.Abs(p.x)>13;
    if(outOfRange){float ahead=z+400+i*57;if(ahead>track.length-25)continue;var target=new Vector3(lanes[i],5.12f,ahead);if(Physics.CheckBox(target+Vector3.up*.6f,new Vector3(1.2f,.7f,3),Quaternion.identity,1<<8))continue;body.position=target;body.rotation=Quaternion.Euler(0,speeds[i]<0?180:0,0);p=target;}
    if(Vector3.Dot(body.transform.up,Vector3.up)<.55f){damage.DisableDrive();continue;}var desired=new Vector3(Mathf.Clamp((lanes[i]-p.x)*2,-2,2),0,speeds[i]);body.AddForce(Vector3.ClampMagnitude((desired-Vector3.ProjectOnPlane(body.linearVelocity,Vector3.up))*3,18),ForceMode.Acceleration);body.AddTorque(Vector3.Cross(body.transform.up,Vector3.up)*5-body.angularVelocity*2,ForceMode.Acceleration);
   }}
 }
